+const M3OpInfo* GetOpInfo(m3opcode_t opcode) {
+    switch (opcode >> 8) {
+    case 0x00:
+    	if (opcode < M3_COUNT_OF(c_operations)) {
+    		return &c_operations[opcode];
+    	}
+    case 0xFC:
+    	opcode &= 0xFF;
+    	if (opcode < M3_COUNT_OF(c_operationsFC)) {
+    		return &c_operationsFC[opcode];
+    	}
+    }
+    return NULL;
+}
